Read column B from the active sheet, remove the leading `400` prefix from each code, and convert the remaining digits to a number so leading zeros disappear. Write those plain numeric results into `A2:A4452`. Save the modified workbook as `OUT`.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if wb.active is None:
    ws = wb.create_sheet("Sheet1")
else:
    ws = wb.active

vws = vals[ws.title] if ws.title in vals.sheetnames else vals[vals.sheetnames[0]]

def transform(value):
    if value is None:
        return None

    if isinstance(value, bool):
        s = str(value)
    elif isinstance(value, float):
        s = str(int(value)) if value.is_integer() else str(value).strip()
    elif isinstance(value, int):
        s = str(value)
    else:
        s = str(value).strip()

    if s.endswith(".0"):
        s = s[:-2]

    tail = s[3:] if s.startswith("400") else s
    tail = tail.strip()

    if tail == "":
        return 0

    try:
        return int(tail)
    except ValueError:
        try:
            return int(float(tail))
        except Exception:
            t = tail.lstrip("0")
            return int(t) if t else 0

count = 0
samples = []

for row in range(2, 4453):
    code = vws.cell(row=row, column=2).value
    result = transform(code)

    if result is None:
        ws.cell(row=row, column=1).value = None
    else:
        ws.cell(row=row, column=1).value = result
        count += 1
        if len(samples) < 5:
            samples.append((row, code, result))

wb.save(OUT)
print("filled", count, "samples", samples)
